INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_07','V906','阮明',7,'好，我先学习基础桌游规则，不勉强自己点奶茶。','hǎo， wǒ xiān xué xí jī chǔ zhuō yóu guī zé， bù miǎn qiǎng zì jǐ diǎn nǎi chá。','Được, vậy mình học luật chơi cơ bản trước, không ép mình gọi trà sữa nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT907','SXH1','参加校园国际文化节，展示本国特色小吃与传统手工',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V907','SIT907','P1','suon_se','ban_chinh_thuc',NULL,'校园国际文化节鼓励各国留学生展示本土美食、手工艺，是跨文化交流、结交各国朋友的重要活动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_01','V907','阮明',1,'老师，我报名文化节摊位，准备越南春卷和手工竹编展示可以吗？','lǎo shī， wǒ bào míng wén huà jié tān wèi， zhǔn bèi yuè nán chūn juǎn hé shǒu gōng zhú biān zhǎn shì kě yǐ ma？','Thầy ơi, em đăng ký gian hàng lễ hội văn hóa, chuẩn bị nem cuốn Việt Nam với trưng bày đan tre thủ công được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_02','V907','老师',2,'完全合适，每个国家摊位提供少量试吃，吸引其他同学参观哦。','wán quán hé shì， měi gè guó jiā tān wèi tí gōng shǎo liàng shì chī， xī yǐn qí tā tóng xué cān guān ó。','Hoàn toàn phù hợp, mỗi gian hàng của các nước sẽ cho nếm thử một chút, thu hút các bạn khác đến tham quan nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_03','V907','阮明',3,'食材采购费用学院有补贴，还是需要留学生自行承担？','shí cái cǎi gòu fèi yòng xué yuàn yǒu bǔ tiē， hái shì xū yào liú xué shēng zì xíng chéng dān？','Chi phí mua nguyên liệu thì khoa có hỗ trợ, hay là lưu học sinh phải tự chi trả ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_04','V907','老师',4,'基础食材学院报销，额外精致配料由个人自愿准备。','jī chǔ shí cái xué yuàn bào xiāo， é wài jīng zhì pèi liào yóu gè rén zì yuàn zhǔn bèi。','Nguyên liệu cơ bản khoa sẽ thanh toán lại, còn nguyên liệu cầu kỳ thêm thì cá nhân tự nguyện chuẩn bị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_05','V907','阮明',5,'我现场简单演示竹编手法，方便来往同学体验手工。','wǒ xiàn chǎng jiǎn dān yǎn shì zhú biān shǒu fǎ， fāng biàn lái wǎng tóng xué tǐ yàn shǒu gōng。','Em sẽ trình diễn trực tiếp cách đan tre đơn giản, để các bạn qua lại có thể trải nghiệm thử luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_06','V907','老师',6,'活动当天人流量很大，提前半小时到场布置摊位。','huó dòng dàng tiān rén liú liàng hěn dà， tí qián bàn xiǎo shí dào chǎng bù zhì tān wèi。','Hôm diễn ra hoạt động lượng người rất đông, em đến sớm nửa tiếng để dọn gian hàng trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_07','V907','阮明',7,'我提前备好食材与手工材料，文化节准时布置摊位。','wǒ tí qián bèi hǎo shí cái yǔ shǒu gōng cái liào， wén huà jié zhǔn shí bù zhì tān wèi。','Em sẽ chuẩn bị sẵn nguyên liệu và đồ thủ công trước, đến đúng giờ dọn gian hàng cho lễ hội văn hóa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT908','SXH2','多人聚餐AA结算，核对账单、分摊转账，有人忘记付款提醒对方',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V908','SIT908','P1','twist','tuy_y',NULL,'多人AA聚餐统一由一人代收款项，提醒未付款人时语气委婉，避免让对方产生被催促的尴尬。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_01','V908','阮明',1,'我把餐厅完整账单发到群里，所有人人均三十五元，核对一下。','wǒ bǎ cān tīng wán zhěng zhàng dān fā dào qún lǐ， suǒ yǒu rén rén jūn sān shí wǔ yuán， hé duì yī xià。','Mình gửi hết hóa đơn nhà hàng lên nhóm rồi, mỗi người ba mươi lăm tệ, mọi người kiểm tra lại giúp mình nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_02','V908','苏雯',2,'大部分人已经转账给我，只有两位同学还没有付款。','dà bù fèn rén yǐ jīng zhuǎn zhàng gěi wǒ， zhǐ yǒu liǎng wèi tóng xué hái méi yǒu fù kuǎn。','Đa số mọi người chuyển khoản cho mình rồi, chỉ còn hai bạn chưa thanh toán thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_03','V908','阮明',3,'可能他们忘记看群消息，我温和提醒一句，别让对方尴尬。','kě néng tā men wàng jì kàn qún xiāo xī， wǒ wēn hé tí xǐng yī jù， bié ràng duì fāng gān gà。','Chắc mấy bạn đó quên xem tin nhắn nhóm, để mình nhắc nhẹ một câu thôi, đừng để họ ngại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_04','V908','苏雯',4,'说得委婉一点，就说我统一收款后要给店家结账。','shuō dé wěi wǎn yì diǎn， jiù shuō wǒ tǒng yī shōu kuǎn hòu yào gěi diàn jiā jié zhàng。','Nói khéo léo một chút thôi, cứ bảo là mình thu tiền xong rồi thanh toán cho quán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_05','V908','阮明',5,'各位，麻烦有空转一下聚餐分摊费，我今晚统一结清账单哈。','gè wèi， má fán yǒu kòng zhuǎn yī xià jù cān fēn tān fèi， wǒ jīn wǎn tǒng yī jié qīng zhàng dān hā。','Mọi người ơi, rảnh thì chuyển khoản tiền chia bữa ăn giúp mình nhé, tối nay mình thanh toán hết luôn hen.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_06','V908','小林',6,'收到，我现在立刻转账，刚才自习完全没看手机。','shōu dào， wǒ xiàn zài lì kè zhuǎn zhàng， gāng cái zì xí wán quán méi kàn shǒu jī。','Nhận được rồi, mình chuyển khoản ngay đây, lúc nãy tự học nên không xem điện thoại luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_07','V908','阮明',7,'全部款项收齐，这次聚餐开销结算完毕。','quán bù kuǎn xiàng shōu qí， zhè cì jù cān kāi xiāo jié suàn wán bì。','Thu đủ hết tiền rồi, chi phí bữa ăn lần này tính xong xuôi hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT909','SXH2','朋友过节送小礼物，推辞几番后礼貌收下并回赠伴手礼',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V909','SIT909','P1','suon_se','tuy_y',NULL,'国内人情讲究礼尚往来，收到礼物会先礼貌推辞一次再收下，后续准备等价小伴手礼回赠对方。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_01','V909','阮明',1,'不用特意给我准备中秋月饼，太破费啦，我不好意思收下。','bù yòng tè yì gěi wǒ zhǔn bèi zhōng qiū yuè bǐng， tài pò fèi la， wǒ bù hǎo yì sī shōu xià。','Không cần đặc biệt chuẩn bị bánh trung thu cho mình đâu, tốn kém quá, mình ngại nhận lắm.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_02','V909','苏雯',2,'只是一盒普通月饼，一点心意，你不用跟我客气。','zhǐ shì yī hé pǔ tōng yuè bǐng， yì diǎn xīn yì， nǐ bù yòng gēn wǒ kè qì。','Chỉ là một hộp bánh trung thu bình thường thôi mà, chút tấm lòng thôi, bạn đừng khách sáo với mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_03','V909','阮明',3,'那我收下这份心意，下周我把家里寄来的越南咖啡回送给你。','nà wǒ shōu xià zhè fèn xīn yì， xià zhōu wǒ bǎ jiā lǐ jì lái de yuè nán kā fēi huí sòng gěi nǐ。','Vậy thì mình nhận tấm lòng này nha, tuần sau mình tặng lại bạn cà phê Việt Nam nhà gửi qua.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_04','V909','苏雯',4,'不用专门回礼，大家朋友之间不用计较这么多。','bù yòng zhuān mén huí lǐ， dà jiā péng yǒu zhī jiān bù yòng jì jiào zhè me duō。','Không cần phải tặng lại đâu, bạn bè với nhau tính toán nhiều làm gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_05','V909','阮明',5,'礼尚往来是我们两国都有的习惯，一定要收下我的伴手礼。','lǐ shàng wǎng lái shì wǒ men liǎng guó dōu yǒu de xí guàn， yí dìng yào shōu xià wǒ de bàn shǒu lǐ。','Có qua có lại là phong tục của cả hai nước mình mà, bạn phải nhận quà của mình đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_06','V909','苏雯',6,'行，那我收下咖啡，下次过节我们简单小礼物互相分享。','xíng， nà wǒ shōu xià kā fēi， xià cì guò jié wǒ men jiǎn dān xiǎo lǐ wù hù xiāng fēn xiǎng。','Được, vậy mình nhận cà phê nha, lần sau đến lễ mình tặng nhau món quà nhỏ đơn giản thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_07','V909','阮明',7,'好，之后节日互相送平价小特产，不用贵重礼品。','hǎo， zhī hòu jié rì hù xiāng sòng píng jià xiǎo tè chǎn， bù yòng guì zhòng lǐ pǐn。','Ừ, sau này cứ lễ tết là tặng nhau đặc sản nhỏ giá bình dân thôi, không cần quà đắt tiền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT910','SXH2','主动请客吃饭，拒绝朋友抢单，解释自己提前规划买单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V910','SIT910','P1','twist','tuy_y',NULL,'朋友之间答谢请客十分常见，对方抢单时会说明请客缘由，约定下次轮流做东，平衡人情往来。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_01','V910','阮明',1,'今天是我请你吃饭，别跟我抢买单，我早就计划好了。','jīn tiān shì wǒ qǐng nǐ chī fàn， bié gēn wǒ qiǎng mǎi dān， wǒ zǎo jiù jì huà hǎo le。','Hôm nay là mình mời bạn ăn cơm, đừng giành trả tiền với mình, mình tính trước hết rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_02','V910','苏雯',2,'不行，每次都是你请客，这次必须我来付钱。','bù xíng， měi cì dōu shì nǐ qǐng kè， zhè cì bì xū wǒ lái fù qián。','Không được, lần nào cũng bạn mời, lần này nhất định mình phải trả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_03','V910','阮明',3,'上次你帮我整理一整本汉语笔记，这次就当答谢你的帮忙嘛。','shàng cì nǐ bāng wǒ zhěng lǐ yī zhěng běn hàn yǔ bǐ jì， zhè cì jiù dāng dá xiè nǐ de bāng máng ma。','Lần trước bạn giúp mình soạn nguyên cuốn vở tiếng Trung, lần này coi như mình cảm ơn bạn đó mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_04','V910','苏雯',4,'只是小事而已，不用专门请客花这么多钱。','zhǐ shì xiǎo shì ér yǐ， bù yòng zhuān mén qǐng kè huā zhè me duō qián。','Chỉ là chuyện nhỏ thôi mà, đâu cần mời ăn tốn nhiều tiền vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_05','V910','阮明',5,'心意一定要收下，下次换你请客，我们轮流做东。','xīn yì yí dìng yào shōu xià， xià cì huàn nǐ qǐng kè， wǒ men lún liú zuò dōng。','Tấm lòng này bạn phải nhận nha, lần sau tới lượt bạn mời, mình thay phiên nhau làm chủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_06','V910','苏雯',6,'那好吧，下次吃饭不许再跟我抢账单。','nà hǎo ba， xià cì chī fàn bù xǔ zài gēn wǒ qiǎng zhàng dān。','Thôi được rồi, lần sau ăn cơm không được giành trả tiền với mình nữa đâu đó.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_07','V910','阮明',7,'没问题，下次聚餐全部由你买单。','méi wèn tí， xià cì jù cān quán bù yóu nǐ mǎi dān。','Không vấn đề gì, lần sau tụ tập ăn uống để bạn trả hết luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT911','SXH2','多人外出喝奶茶，提前说好各自付款，避免互相垫付混淆',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V911','SIT911','P1','suon_se','tuy_y',NULL,'小额饮品、小吃分开自行付款，是年轻人简化人情、避免垫付纠纷的通用社交方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_01','V911','阮明',1,'我们去奶茶店，大家各自扫码点单自己付款，免得之后算不清垫付。','wǒ men qù nǎi chá diàn， dà jiā gè zì sǎo mǎ diǎn dān zì jǐ fù kuǎn， miǎn de zhī hòu suàn bù qīng diàn fù。','Mình đi quán trà sữa nha, ai nấy quét mã gọi món tự trả tiền luôn, khỏi sau này tính toán tiền ứng trước rối tung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_02','V911','小林',2,'有时候有人手机没电，临时垫付之后很容易忘记转账。','yǒu shí hòu yǒu rén shǒu jī méi diàn， lín shí diàn fù zhī hòu hěn róng yì wàng jì zhuǎn zhàng。','Có lúc có người hết pin điện thoại, ứng tiền trước xong dễ quên chuyển khoản lại lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_03','V911','阮明',3,'分开付款最省事，不用事后挨个核对转账记录。','fēn kāi fù kuǎn zuì shěng shì， bù yòng shì hòu āi gè hé duì zhuǎn zhàng jì lù。','Trả tiền riêng là tiện nhất, khỏi phải sau đó kiểm từng người xem chuyển khoản chưa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_04','V911','苏雯',4,'行，到店每个人自己下单，不用统一一个人买单。','xíng， dào diàn měi gè rén zì jǐ xià dān， bù yòng tǒng yī yí gè rén mǎi dān。','Được, tới quán ai nấy tự gọi món, không cần một người trả hết đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_05','V911','阮明',5,'想喝什么直接点，不用顾虑饮品价格互相迁就。','xiǎng hē shén me zhí jiē diǎn， bù yòng gù lǜ yǐn pǐn jià gé hù xiāng qiān jiù。','Muốn uống gì cứ gọi thoải mái, khỏi phải ngại giá cả mà nhường nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_06','V911','小林',6,'这个办法省心，避免一堆转账记录分不清谁欠谁。','zhè ge bàn fǎ shěng xīn， bì miǎn yī duī zhuǎn zhàng jì lù fēn bù qīng shuí qiàn shuí。','Cách này đỡ đau đầu ghê, khỏi phải rối một đống lịch sử chuyển khoản không biết ai nợ ai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_07','V911','阮明',7,'那我们现在去奶茶店各自下单。','nà wǒ men xiàn zài qù nǎi chá diàn gè zì xià dān。','Vậy giờ mình đi quán trà sữa, ai nấy tự gọi món nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT912','SXH2','朋友生病住院，邀约同学一起买水果前去探望慰问',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V912','SIT912','P1','suon_se','ban_chinh_thuc',NULL,'国内探望病人有送礼禁忌，梨谐音"离"不宜赠送；多人结伴探望、控制时长，不打扰病人休养。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_01','V912','阮明',1,'听说小杨发烧住院，我们约几个朋友买水果去医院看望他吧？','tīng shuō xiǎo yáng fā shāo zhù yuàn， wǒ men yuē jǐ gè péng yǒu mǎi shuǐ guǒ qù yī yuàn kàn wàng tā ba？','Nghe nói Tiểu Dương bị sốt phải nhập viện, mình rủ vài người bạn mua trái cây đến bệnh viện thăm bạn ấy nhé?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_02','V912','小林',2,'可以，医院适合送苹果、橙子这类温和水果，不要送梨。','kě yǐ， yī yuàn shì hé sòng píng guǒ、 chéng zi zhè lèi wēn hé shuǐ guǒ， bú yào sòng lí。','Được đó, đi bệnh viện thì nên tặng táo, cam kiểu trái cây dịu nhẹ, đừng tặng lê.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_03','V912','阮明',3,'梨在中文谐音不吉利，探望病人确实不适合携带对吧？','lí zài zhōng wén xié yīn bù jí lì， tàn wàng bìng rén què shí bú shì hé xié dài duì ba？','Trong tiếng Trung chữ lê đọc gần âm không may mắn, đi thăm bệnh nhân đúng là không nên mang theo phải không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_04','V912','小林',4,'没错，我们四个人凑钱买一箱鲜果，统一分摊费用。','méi cuò， wǒ men sì gè rén còu qián mǎi yī xiāng xiān guǒ， tǒng yī fēn tān fèi yòng。','Đúng vậy, bốn người mình góp tiền mua một thùng trái cây tươi, chia đều chi phí ra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_05','V912','阮明',5,'下午没课，三点左右在医院楼下集合一起上楼探望。','xià wǔ méi kè， sān diǎn zuǒ yòu zài yī yuàn lóu xià jí hé yī qǐ shàng lóu tàn wàng。','Chiều nay không có tiết, khoảng ba giờ mình tập trung dưới sảnh bệnh viện rồi cùng lên thăm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_06','V912','小林',6,'探望时间控制半小时，不耽误病人休息恢复。','tàn wàng shí jiān kòng zhì bàn xiǎo shí， bù dān wù bìng rén xiū xī huī fù。','Thời gian thăm chỉ nên khoảng nửa tiếng thôi, để không ảnh hưởng đến việc nghỉ ngơi hồi phục của bệnh nhân.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_07','V912','阮明',7,'我现在联系其他同学，敲定下午探望时间。','wǒ xiàn zài lián xì qí tā tóng xué， qiāo dìng xià wǔ tàn wàng shí jiān。','Giờ mình liên hệ mấy bạn khác để chốt giờ thăm buổi chiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT913','SXH2','节日邀请中国朋友来宿舍，亲手做越南特色饭菜招待',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V913','SIT913','P1','twist','tuy_y',NULL,'邀请好友到宿舍亲手做饭招待，代表十分重视这段友谊，是很真诚的社交待客方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_01','V913','阮明',1,'中秋宿舍不熄灯，你来我宿舍，我亲手做越南米粉招待你。','zhōng qiū sù shè bù xī dēng， nǐ lái wǒ sù shè， wǒ qīn shǒu zuò yuè nán mǐ fěn zhāo dài nǐ。','Trung thu ký túc xá không tắt đèn đâu, bạn qua phòng mình đi, mình tự tay nấu phở Việt Nam đãi bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_02','V913','苏雯',2,'太麻烦你了，买菜、做饭收拾要花很长时间。','tài má fán nǐ le， mǎi cài、 zuò fàn shōu shí yào huā hěn zhǎng shí jiān。','Phiền bạn quá vậy, đi chợ, nấu nướng rồi dọn dẹp chắc tốn nhiều thời gian lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_03','V913','阮明',3,'食材我已经提前网购备好，只需要简单蒸煮，不会很费力嘛。','shí cái wǒ yǐ jīng tí qián wǎng gòu bèi hǎo， zhǐ xū yào jiǎn dān zhēng zhǔ， bú huì hěn fèi lì ma。','Nguyên liệu mình đặt mua online chuẩn bị sẵn rồi, chỉ cần hấp nấu đơn giản thôi, không tốn công đâu mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_04','V913','苏雯',4,'我带一盒月饼过去搭配晚餐，咱们两国小吃一起品尝。','wǒ dài yī hé yuè bǐng guò qù dā pèi wǎn cān， zán men liǎng guó xiǎo chī yì qǐ pǐn cháng。','Mình mang theo một hộp bánh trung thu qua ăn kèm bữa tối, mình cùng thưởng thức món ăn của hai nước luôn nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_05','V913','阮明',5,'宿舍小电锅功率有限，菜品种类不多，你别嫌弃简单。','sù shè xiǎo diàn guō gōng lǜ yǒu xiàn， cài pǐn zhǒng lèi bù duō， nǐ bié xián qì jiǎn dān。','Nồi điện trong ký túc xá công suất nhỏ, món ăn không được nhiều đâu, bạn đừng chê đơn giản nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_06','V913','苏雯',6,'亲手做的饭菜比外面餐厅更有心意，我很期待。','qīn shǒu zuò de fàn cài bǐ wài miàn cān tīng gèng yǒu xīn yì， wǒ hěn qī dài。','Đồ ăn tự tay nấu còn có tâm hơn ngoài tiệm nhiều, mình mong lắm luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_07','V913','阮明',7,'那晚上七点来宿舍，我们一起过节聊天。','nà wǎn shàng qī diǎn lái sù shè， wǒ men yì qǐ guò jié liáo tiān。','Vậy bảy giờ tối qua phòng mình nha, mình cùng đón lễ và tám chuyện luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT914','SXH2','收到朋友贵重礼物，担心人情过重，和对方沟通下次减少花销',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V914','SIT914','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内朋友交往更推崇平价走心小礼物，贵重礼品容易让对方产生人情压力，双方会提前约定简化送礼开销。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_01','V914','阮明',1,'这条围巾价格太高，贵重礼物我收下心里很过意不去。','zhè tiáo wéi jīn jià gé tài gāo， guì zhòng lǐ wù wǒ shōu xià xīn lǐ hěn guò yì bù qù。','Chiếc khăn quàng này giá trị quá cao, nhận món quà đắt tiền như vậy mình thấy áy náy trong lòng lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_02','V914','苏雯',2,'只是一份生日礼物，不用放在心上。','zhǐ shì yī fèn shēng rì lǐ wù， bù yòng fàng zài xīn shàng。','Chỉ là quà sinh nhật thôi mà, bạn đừng bận tâm quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_03','V914','阮明',3,'普通平价小特产就足够，这么贵重的礼物让我不知道怎么回礼。','pǔ tōng píng jià xiǎo tè chǎn jiù zú gòu， zhè me guì zhòng de lǐ wù ràng wǒ bù zhī dào zěn me huí lǐ。','Chỉ cần đặc sản nhỏ bình dân thôi là đủ rồi, quà quý giá thế này khiến mình không biết đáp lễ sao cho phải.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_04','V914','苏雯',4,'朋友不用刻意计较礼物价值，不用非要等价回赠。','péng yǒu bù yòng kè yì jì jiào lǐ wù jià zhí， bù yòng fēi yào děng jià huí zèng。','Bạn bè với nhau đâu cần tính toán giá trị món quà, cũng không nhất thiết phải tặng lại thứ tương xứng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_05','V914','阮明',5,'下次过节千万不要买高价礼品，不然我不敢再收你的礼物了。','xià cì guò jié qiān wàn bú yào mǎi gāo jià lǐ pǐn， bù rán wǒ bù gǎn zài shōu nǐ de lǐ wù le。','Lần sau đến lễ tết xin đừng mua quà đắt tiền nữa, không thì mình không dám nhận quà của bạn nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_06','V914','苏雯',6,'好，之后只送零食、书签这类平价小物件。','hǎo， zhī hòu zhǐ sòng líng shí、 shū qiān zhè lèi píng jià xiǎo wù jiàn。','Được rồi, sau này chỉ tặng đồ ăn vặt, bookmark những món nhỏ giá bình dân thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_07','V914','阮明',7,'这样轻松相处，不用因为人情礼物有心理负担。','zhè yàng qīng sōng xiāng chǔ， bù yòng yīn wèi rén qíng lǐ wù yǒu xīn lǐ fù dān。','Như vậy chơi với nhau thoải mái hơn, không phải áp lực tâm lý vì chuyện quà cáp tình cảm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT915','SXH3','因中外饮食礼仪差异产生小尴尬，主动和朋友解释本国习惯',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V915','SIT915','P1','suon_se','tuy_y',NULL,'中外餐桌礼仪存在大量差异，出现小尴尬主动说明本国习惯，多数中国年轻人会包容理解，不会苛责。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_01','V915','阮明',1,'刚刚吃饭我直接端碗喝汤，是不是和国内餐桌礼仪不一样？','gāng gāng chī fàn wǒ zhí jiē duān wǎn hē tāng， shì bú shì hé guó nèi cān zhuō lǐ yí bù yí yàng？','Lúc nãy ăn cơm mình bưng chén húp canh trực tiếp luôn, có phải khác với phép tắc bàn ăn ở đây không ta?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_02','V915','苏雯',2,'这边习惯碗放在桌上喝汤，我还以为你不太适应菜品。','zhè biān xí guàn wǎn fàng zài zhuō shàng hē tāng， wǒ hái yǐ wéi nǐ bù tài shì yìng cài pǐn。','Ở đây quen để chén trên bàn rồi húp canh, mình còn tưởng bạn không hợp món ăn chứ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_03','V915','阮明',3,'越南日常吃饭都会端起碗，是从小养成的饮食习惯，没有失礼的意思。','yuè nán rì cháng chī fàn dōu huì duān qǐ wǎn， shì cóng xiǎo yǎng chéng de yǐn shí xí guàn， méi yǒu shī lǐ de yì si。','Ở Việt Nam ăn cơm hàng ngày đều bưng chén lên hết, đó là thói quen ăn uống từ nhỏ, không có ý gì thất lễ đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_04','V915','苏雯',4,'原来是两国礼仪差别，完全没关系，我能理解。','yuán lái shì liǎng guó lǐ yí chā bié， wán quán méi guān xì， wǒ néng lǐ jiě。','Thì ra là khác biệt văn hóa giữa hai nước thôi, không sao đâu, mình hiểu mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_05','V915','阮明',5,'下次聚餐我会注意入乡随俗，兼顾这边餐桌习惯。','xià cì jù cān wǒ huì zhù yì rù xiāng suí sú， jiān gù zhè biān cān zhuō xí guàn。','Lần sau tụ tập ăn uống mình sẽ chú ý nhập gia tùy tục, để ý thói quen bàn ăn ở đây hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_06','V915','苏雯',6,'不用刻意改变自己，两国习俗不同很正常，不用拘谨。','bù yòng kè yì gǎi biàn zì jǐ， liǎng guó xí sú bù tóng hěn zhèng cháng， bù yòng jū jǐn。','Không cần phải cố gắng thay đổi bản thân đâu, phong tục hai nước khác nhau là chuyện bình thường mà, đừng gò bó quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_07','V915','阮明',7,'谢谢你包容不同的饮食礼仪，不会让我觉得尴尬。','xiè xiè nǐ bāo róng bù tóng de yǐn shí lǐ yí， bú huì ràng wǒ jué de gān gà。','Cảm ơn bạn đã bao dung với sự khác biệt trong phép tắc ăn uống, không làm mình thấy ngại chút nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT916','SXH3','说话直爽无意间冒犯中国同学，事后主动道歉、说明文化差异',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V916','SIT916','P1','twist','ban_chinh_thuc',NULL,'东南亚部分国家交流风格直白，和国内委婉含蓄的沟通方式有冲突，产生矛盾后主动解释文化差异并道歉，容易化解隔阂。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_01','V916','阮明',1,'昨天聊天我说话太直接，伤到你的感受，我郑重跟你道歉。','zuó tiān liáo tiān wǒ shuō huà tài zhí jiē， shāng dào nǐ de gǎn shòu， wǒ zhèng zhòng gēn nǐ dào qiàn。','Hôm qua nói chuyện tôi ăn nói quá thẳng thắn, làm tổn thương cảm xúc của bạn, tôi xin lỗi bạn một cách chân thành.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_02','V916','小林',2,'当时听完心里有点不舒服，知道你不是恶意就没关系。','dāng shí tīng wán xīn lǐ yǒu diǎn bù shū fú， zhī dào nǐ bú shì è yì jiù méi guān xì。','Lúc đó nghe xong tôi cũng thấy hơi khó chịu, nhưng biết bạn không cố ý nên không sao đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_03','V916','阮明',3,'越南日常交流说话更直白，我还没完全适应委婉的中文表达。','yuè nán rì cháng jiāo liú shuō huà gèng zhí bái， wǒ hái méi wán quán shì yìng wěi wǎn de zhōng wén biǎo dá。','Người Việt giao tiếp hàng ngày thường thẳng thắn hơn, tôi vẫn chưa quen hẳn với cách nói chuyện khéo léo của người Trung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_04','V916','小林',4,'我明白文化差异，之后有不舒服我会直接跟你说。','wǒ míng bái wén huà chā yì， zhī hòu yǒu bù shū fú wǒ huì zhí jiē gēn nǐ shuō。','Tôi hiểu là do khác biệt văn hóa, sau này có gì không thoải mái tôi sẽ nói thẳng với bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_05','V916','阮明',5,'之后我说话多斟酌用词，学着更委婉温和地表达想法。','zhī hòu wǒ shuō huà duō zhēn zhuó yòng cí， xué zhe gèng wěi wǎn wēn hé dì biǎo dá xiǎng fǎ。','Sau này tôi sẽ cân nhắc lời nói kỹ hơn, học cách diễn đạt khéo léo, nhẹ nhàng hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_06','V916','小林',6,'我们互相包容两国说话习惯，不用因为小事隔阂。','wǒ men hù xiāng bāo róng liǎng guó shuō huà xí guàn， bù yòng yīn wèi xiǎo shì gé hé。','Chúng ta cùng thông cảm cho thói quen ăn nói của hai nước, đừng vì chuyện nhỏ mà thấy xa cách nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_07','V916','阮明',7,'非常感谢你愿意原谅我无心的冒犯。','fēi cháng gǎn xiè nǐ yuàn yì yuán liàng wǒ wú xīn de mào fàn。','Cảm ơn bạn rất nhiều vì đã sẵn lòng tha thứ cho sự vô ý của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT917','SXH3','和中国朋友聊两国节日风俗，互相讲解本土传统习俗',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V917','SIT917','P1','suon_se','tuy_y',NULL,'聊节日、民俗是安全无冲突的跨文化社交话题，很容易拉近留学生与中国同学的距离。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_01','V917','阮明',1,'越南新年会摆很多鲜花祭祖，你们春节主要有哪些习俗？','yuè nán xīn nián huì bǎi hěn duō xiān huā jì zǔ， nǐ men chūn jié zhǔ yào yǒu nǎ xiē xí sú？','Tết của người Việt hay bày nhiều hoa tươi để cúng tổ tiên, còn Tết của các bạn có những phong tục gì chính vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_02','V917','苏雯',2,'贴春联、包饺子、全家守岁，长辈还给晚辈发红包呢。','tiē chūn lián、 bāo jiǎo zi、 quán jiā shǒu suì， zhǎng bèi huán gěi wǎn bèi fā hóng bāo ne。','Dán câu đối, gói sủi cảo, cả nhà thức đón giao thừa, người lớn còn lì xì cho con cháu nữa đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_03','V917','阮明',3,'我们也有压岁钱，只是发放的时间、包装和中国不一样。','wǒ men yě yǒu yā suì qián， zhǐ shì fā fàng de shí jiān、 bāo zhuāng hé zhōng guó bù yí yàng。','Bên mình cũng có lì xì, chỉ là thời điểm phát, cách gói với bên Trung không giống nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_04','V917','苏雯',4,'中秋你们也会赏月吃月饼吗，还是有特色本土点心？','zhōng qiū nǐ men yě huì shǎng yuè chī yuè bǐng ma， hái shì yǒu tè sè běn tǔ diǎn xīn？','Trung thu bên bạn cũng ngắm trăng ăn bánh trung thu à, hay có bánh đặc trưng riêng?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_05','V917','阮明',5,'我们有同类团圆节日，点心是糯米团子，风味完全不同。','wǒ men yǒu tóng lèi tuán yuán jié rì， diǎn xīn shì nuò mǐ tuán zi， fēng wèi wán quán bù tóng。','Bên mình cũng có ngày đoàn viên tương tự, món bánh là bánh trôi nếp, hương vị khác hẳn luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_06','V917','苏雯',6,'有空交换各自节日照片，直观看看两国节日场景。','yǒu kòng jiāo huàn gè zì jié rì zhào piān， zhí guān kàn kàn liǎng guó jié rì chǎng jǐng。','Lúc nào rảnh trao đổi ảnh ngày lễ của nhau đi, để xem trực quan không khí lễ tết hai nước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_07','V917','阮明',7,'好，多交流民俗，能更了解彼此国家文化。','hǎo， duō jiāo liú mín sú， néng gèng liǎo jiě bǐ cǐ guó jiā wén huà。','Được đó, trao đổi phong tục nhiều hơn sẽ hiểu văn hóa của nhau rõ hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT918','SXH3','不清楚国内送礼禁忌，请教同学哪些礼物不适合送给长辈朋友',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V918','SIT918','P1','suon_se','ban_chinh_thuc',NULL,'中文大量谐音送礼禁忌，钟表（送终）、梨（离）、伞（散）均为送礼避讳物品，留学生提前询问可避免失礼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_01','V918','阮明',1,'我想给中国长辈准备礼物，想问问有什么物品不能赠送？','wǒ xiǎng gěi zhōng guó zhǎng bèi zhǔn bèi lǐ wù， xiǎng wèn wèn yǒu shén me wù pǐn bù néng zèng sòng？','Tôi muốn chuẩn bị quà cho người lớn tuổi bên Trung, muốn hỏi có món nào không nên tặng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_02','V918','苏雯',2,'钟表、梨、雨伞这几类谐音不吉利，尽量避开哦。','zhōng biǎo、 lí、 yǔ sǎn zhè jǐ lèi xié yīn bù jí lì， jǐn liàng bì kāi ó。','Đồng hồ, lê, ô dù mấy thứ này đọc âm không may mắn, nên tránh nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_03','V918','阮明',3,'送鲜花有没有讲究，白色、黄色花束适合探望长辈吗？','sòng xiān huā yǒu méi yǒu jiǎng jiū， bái sè、 huáng sè huā shù shì hé tàn wàng zhǎng bèi ma？','Tặng hoa tươi có kiêng kỵ gì không, bó hoa trắng, vàng có hợp để thăm người lớn tuổi không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_04','V918','苏雯',4,'白黄鲜花多用于丧葬，看望长辈选红色、粉色鲜花更合适。','bái huáng xiān huā duō yòng yú sāng zàng， kàn wàng zhǎng bèi xuǎn hóng sè、 fěn sè xiān huā gèng hé shì。','Hoa trắng vàng thường dùng trong tang lễ, thăm người lớn tuổi nên chọn hoa đỏ, hoa hồng thì hợp hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_05','V918','阮明',5,'刀具也不能作为礼品赠送，代表分割分离的寓意对吧？','dāo jù yě bù néng zuò wéi lǐ pǐn zèng sòng， dài biǎo fēn gē fēn lí de yù yì duì ba？','Dao kéo cũng không nên làm quà tặng, vì mang ý nghĩa chia cắt, xa lìa đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_06','V918','苏雯',6,'没错，刀具寓意不好，食品、茶叶、丝巾是稳妥选择。','méi cuò， dāo jù yù yì bù hǎo， shí pǐn、 chá yè、 sī jīn shì wěn tuǒ xuǎn zé。','Đúng vậy, dao kéo ý nghĩa không tốt, đồ ăn, trà, khăn lụa là lựa chọn an toàn hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_07','V918','阮明',7,'我记下所有禁忌，挑选稳妥礼品送给长辈。','wǒ jì xià suǒ yǒu jìn jì， tiāo xuǎn wěn tuǒ lǐ pǐn sòng gěi zhǎng bèi。','Tôi ghi nhớ hết mấy điều kiêng kỵ rồi, sẽ chọn quà an toàn để tặng người lớn tuổi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT919','SXH3','朋友调侃本国文化，温和表达自己的看法，避免争执',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V919','SIT919','P1','that_bai_nhe','tuy_y',NULL,'国内年轻人偶尔会随口开玩笑，但涉及他国文化、风俗时需把握分寸，温和表达不适能有效避免社交矛盾升级。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_01','V919','阮明',1,'你刚刚调侃越南饮食的话，听着我心里有点不舒服。','nǐ gāng gāng tiáo kǎn yuè nán yǐn shí de huà， tīng zhe wǒ xīn lǐ yǒu diǎn bù shū fú。','Câu bạn vừa trêu chọc về ẩm thực Việt Nam, nghe xong tôi thấy hơi khó chịu trong lòng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_02','V919','小林',2,'我只是随口开玩笑，没有贬低你国家的意思。','wǒ zhǐ shì suí kǒu kāi wán xiào， méi yǒu biǎn dī nǐ guó jiā de yì si。','Tôi chỉ nói đùa cho vui thôi, không có ý coi thường đất nước bạn đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_03','V919','阮明',3,'每个国家饮食文化都值得尊重，玩笑最好不要拿本国特色调侃嘛。','měi gè guó jiā yǐn shí wén huà dōu zhí de zūn zhòng， wán xiào zuì hǎo bù yào ná běn guó tè sè diào kǎn ma。','Văn hóa ẩm thực của mỗi nước đều đáng được tôn trọng, đùa giỡn thì tốt nhất đừng lấy đặc trưng của nước người ta ra chọc mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_04','V919','小林',4,'我不清楚你会在意这个，之后我会注意说话分寸。','wǒ bù qīng chǔ nǐ huì zài yì zhè ge， zhī hòu wǒ huì zhù yì shuō huà fēn cùn。','Tôi không biết bạn để ý chuyện này, sau này tôi sẽ chú ý chừng mực khi nói.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_05','V919','阮明',5,'我们可以客观对比两国美食，但不要用调侃、取笑的语气。','wǒ men kě yǐ kè guān duì bǐ liǎng guó měi shí， dàn bú yào yòng tiáo kǎn、 qǔ xiào de yǔ qì。','Chúng ta có thể so sánh khách quan món ăn hai nước, nhưng đừng dùng giọng điệu trêu chọc, cười cợt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_06','V919','小林',6,'我记住了，以后聊各国文化都会注意措辞。','wǒ jì zhù le， yǐ hòu liáo gè guó wén huà dōu huì zhù yì cuò cí。','Tôi nhớ rồi, sau này nói chuyện văn hóa các nước tôi sẽ chú ý lời lẽ hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_07','V919','阮明',7,'谢谢你理解我的感受，我们继续友好聊天。','xiè xiè nǐ lǐ jiě wǒ de gǎn shòu， wǒ men jì xù yǒu hǎo liáo tiān。','Cảm ơn bạn đã hiểu cho cảm xúc của tôi, chúng ta tiếp tục nói chuyện vui vẻ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT920','SXH3','线上聊天用词误会，线下见面澄清、化解线上尴尬',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V920','SIT920','P1','twist','ban_chinh_thuc',NULL,'纯文字线上聊天缺少语气表情，极易产生误会，国内朋友遇到分歧倾向线下当面澄清，高效化解尴尬。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_01','V920','阮明',1,'昨天线上聊天那句话我用词有误，让你误会我的意思了。','zuó tiān xiàn shàng liáo tiān nà jù huà wǒ yòng cí yǒu wù， ràng nǐ wù huì wǒ de yì si le。','Câu tôi nhắn hôm qua dùng từ không ổn, khiến bạn hiểu lầm ý của tôi mất rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_02','V920','苏雯',2,'文字看不到语气，我当时还以为你有点生气。','wén zì kàn bú dào yǔ qì， wǒ dāng shí hái yǐ wéi nǐ yǒu diǎn shēng qì。','Nhắn tin không thấy được giọng điệu, lúc đó tôi còn tưởng bạn hơi giận nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_03','V920','阮明',3,'线上打字缺少表情，很容易曲解情绪，我今天当面跟你解释清楚。','xiàn shàng dǎ zì quē shǎo biǎo qíng， hěn róng yì qū jiě qíng xù， wǒ jīn tiān dāng miàn gēn nǐ jiě shì qīng chǔ。','Nhắn tin online thiếu biểu cảm nên rất dễ hiểu sai cảm xúc, hôm nay tôi gặp trực tiếp giải thích rõ với bạn luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_04','V920','苏雯',4,'线下聊开就没事了，之后重要事情尽量语音沟通。','xiàn xià liáo kāi jiù méi shì le， zhī hòu zhòng yào shì qíng jǐn liàng yǔ yīn gōu tōng。','Gặp trực tiếp nói rõ ra là ổn rồi, sau này chuyện quan trọng thì cố gắng gọi điện trao đổi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_05','V920','阮明',5,'文字容易产生误会，之后复杂想法直接语音或者见面聊。','wén zì róng yì chǎn shēng wù huì， zhī hòu fù zá xiǎng fǎ zhí jiē yǔ yīn huò zhě jiàn miàn liáo。','Nhắn tin dễ gây hiểu lầm, sau này suy nghĩ phức tạp thì gọi thoại hoặc gặp mặt nói chuyện trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_06','V920','苏雯',6,'没问题，线上简单小事文字，重要话题线下沟通。','méi wèn tí， xiàn shàng jiǎn dān xiǎo shì wén zì， zhòng yào huà tí xiàn xià gōu tōng。','Không vấn đề gì, chuyện nhỏ đơn giản thì nhắn tin, chuyện quan trọng thì gặp trực tiếp trao đổi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_07','V920','阮明',7,'太好了，误会说开我们不会有隔阂。','tài hǎo le， wù huì shuō kāi wǒ men bú huì yǒu gé hé。','Tốt quá, hiểu lầm đã nói rõ rồi thì chúng ta sẽ không còn khoảng cách nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT921','SXH4','留学生微信群发起线下小型茶话会，统计参与人数、地点',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V921','SIT921','P1','suon_se','tuy_y',NULL,'留学生线上社群自发组织线下小型聚会十分普遍，饮品、零食自带或AA分摊，场地提前预留。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_01','V921','阮明',1,'本周六下午两点校内咖啡馆举办留学生茶话会，有意向的群里回复1。','běn zhōu liù xià wǔ liǎng diǎn xiào nèi kā fēi guǎn jǔ bàn liú xué shēng chá huà huì， yǒu yì xiàng de qún lǐ huí fù 1。','Thứ Bảy tuần này lúc hai giờ chiều tổ chức buổi trà chiều cho du học sinh tại quán cà phê trong trường, bạn nào muốn tham gia thì trả lời 1 trong nhóm nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_02','V921','群友A',2,'咖啡馆座位有限，最多容纳十五个人，人数满了就截止报名吗？','kā fēi guǎn zuò wèi yǒu xiàn， zuì duō róng nà shí wǔ gè rén， rén shù mǎn le jiù jié zhǐ bào míng ma？','Quán cà phê có giới hạn chỗ ngồi, tối đa chứa được mười lăm người, đủ số là ngừng nhận đăng ký luôn hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_03','V921','阮明',3,'没错，先回复先预留位置，到场饮品全部AA自行点单。','méi cuò， xiān huí fù xiān yù liú wèi zhì， dào chǎng yǐn pǐn quán bù AA zì xíng diǎn dān。','Đúng rồi, ai trả lời trước thì được giữ chỗ trước, đến nơi thức uống thì mọi người tự gọi tự trả tiền nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_04','V921','群友B',4,'会分享各国零食吗，我可以带越南特色糖果过去。','huì fēn xiǎng gè guó líng shí ma， wǒ kě yǐ dài yuè nán tè sè táng guǒ guò qù。','Có chia sẻ đồ ăn vặt các nước không, mình có thể mang kẹo đặc sản Việt Nam qua đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_05','V921','阮明',5,'欢迎大家自带本国小零食交换品尝，丰富茶话会内容。','huān yíng dà jiā zì dài běn guó xiǎo líng shí jiāo huàn pǐn cháng， fēng fù chá huà huì nèi róng。','Rất hoan nghênh mọi người mang đồ ăn vặt nước mình để trao đổi nếm thử, cho buổi trà chiều thêm phong phú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_06','V921','阮明',6,'我傍晚统计最终人数，提前跟咖啡馆预留区域。','wǒ bàng wǎn tǒng jì zuì zhōng rén shù， tí qián gēn kā fēi guǎn yù liú qū yù。','Chiều tối mình sẽ chốt số lượng người tham gia, rồi báo trước để quán cà phê giữ chỗ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_07','V921','群友C',7,'我报名参加，周六准时到场。','wǒ bào míng cān jiā， zhōu liù zhǔn shí dào chǎng。','Mình đăng ký tham gia, thứ Bảy sẽ đến đúng giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT922','SXH4','和新朋友初次线下见面，挑选公共场所、确认往返交通',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V922','SIT922','P1','twist','ban_chinh_thuc',NULL,'初次线下见面优先校园周边公共场所，不单独前往偏僻地点，分别后互相报平安是国内年轻人通用社交安全习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_01','V922','阮明',1,'我们第一次线下见面，选学校正门连锁奶茶店可以吗？','wǒ men dì yī cì xiàn xià jiàn miàn， xuǎn xué xiào zhèng mén lián suǒ nǎi chá diàn kě yǐ ma？','Lần đầu gặp mặt trực tiếp, chọn quán trà sữa chuỗi ở cổng chính trường được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_02','V922','陈雨',2,'公共场所很安全，就是我下午有课，只能停留一小时。','gōng gòng chǎng suǒ hěn ān quán， jiù shì wǒ xià wǔ yǒu kè， zhǐ néng tíng liú yī xiǎo shí。','Chỗ công cộng thì an toàn, chỉ là chiều mình có tiết học, chỉ ở lại được một tiếng thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_03','V922','阮明',3,'一小时足够简单聊天，结束我可以送你回教学楼。','yī xiǎo shí zú gòu jiǎn dān liáo tiān， jié shù wǒ kě yǐ sòng nǐ huí jiào xué lóu。','Một tiếng cũng đủ để nói chuyện đơn giản rồi, xong mình có thể đưa bạn về tòa nhà học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_04','V922','陈雨',4,'不用特意送我，校门口公交直达教学楼，交通很方便。','bù yòng tè yì sòng wǒ， xiào mén kǒu gōng jiāo zhí dá jiào xué lóu， jiāo tōng hěn fāng biàn。','Không cần đưa mình đâu, xe buýt ở cổng trường đi thẳng tới tòa nhà học, tiện lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_05','V922','阮明',5,'见面结束记得发消息告诉我平安抵达教室哈。','jiàn miàn jié shù jì de fā xiāo xī gào sù wǒ píng ān dǐ dá jiào shì hā。','Gặp xong nhớ nhắn tin báo mình là đã về lớp an toàn nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_06','V922','陈雨',6,'好，周六下午三点奶茶店门口碰面。','hǎo， zhōu liù xià wǔ sān diǎn nǎi chá diàn mén kǒu pèng miàn。','Được, ba giờ chiều thứ Bảy gặp nhau trước cửa quán trà sữa nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_07','V922','阮明',7,'准时赴约，初次见面简单聊一聊各自专业。','zhǔn shí fù yuē， chū cì jiàn miàn jiǎn dān liáo yī liáo gè zì zhuān yè。','Đúng giờ tới nhé, lần đầu gặp mặt thì nói chuyện đơn giản về chuyên ngành của nhau thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT923','SXH4','朋友频繁发消息打扰自习，委婉告知自己的作息学习时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V923','SIT923','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内学生重视自习、上课时间，会主动和朋友说明固定专注时段，委婉划定社交边界，对方一般都会体谅。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_01','V923','阮明',1,'不好意思，每天下午两点到五点我要专心自习，没法及时回复消息。','bù hǎo yì sī， měi tiān xià wǔ liǎng diǎn dào wǔ diǎn wǒ yào zhuān xīn zì xí， méi fǎ jí shí huí fù xiāo xī。','Xin lỗi bạn, mỗi ngày từ hai giờ đến năm giờ chiều mình cần tập trung tự học, không kịp trả lời tin nhắn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_02','V923','小杨',2,'我以为你随时有空，一有琐事就发消息打扰你了。','wǒ yǐ wéi nǐ suí shí yǒu kòng， yī yǒu suǒ shì jiù fā xiāo xī dǎ rǎo nǐ le。','Mình cứ tưởng bạn lúc nào cũng rảnh, có việc vặt là nhắn làm phiền bạn luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_03','V923','阮明',3,'自习时段需要安静专注，其余晚上七点之后我可以随时聊天嘛。','zì xí shí duàn xū yào ān jìng zhuān zhù， qí yú wǎn shàng qī diǎn zhī hòu wǒ kě yǐ suí shí liáo tiān ma。','Khung giờ tự học cần yên tĩnh tập trung, còn lại từ bảy giờ tối trở đi mình có thể trò chuyện thoải mái mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_04','V923','小杨',4,'我记住你的作息，非休息时间不会频繁发消息打断你学习。','wǒ jì zhù nǐ de zuò xī， fēi xiū xī shí jiān bú huì pín fán fā xiāo xī dǎ duàn nǐ xué xí。','Mình ghi nhớ giờ giấc của bạn rồi, ngoài giờ nghỉ sẽ không nhắn tin liên tục làm gián đoạn việc học của bạn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_05','V923','阮明',5,'急事可以直接打电话，普通闲聊集中晚上再回复你。','jí shì kě yǐ zhí jiē dǎ diàn huà， pǔ tōng xián liáo jí zhōng wǎn shàng zài huí fù nǐ。','Việc gấp thì cứ gọi điện thẳng, chuyện tán gẫu bình thường thì để tối mình trả lời sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_06','V923','小杨',6,'没问题，我调整发消息的时间，不耽误你复习功课。','méi wèn tí， wǒ tiáo zhěng fā xiāo xī de shí jiān， bù dān wù nǐ fù xí gōng kè。','Không vấn đề gì, mình sẽ điều chỉnh giờ nhắn tin, không làm ảnh hưởng đến việc ôn bài của bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_07','V923','阮明',7,'十分感谢理解，我们错开自习时段聊天互不影响。','shí fēn gǎn xiè lǐ jiě， wǒ men cuò kāi zì xí shí duàn liáo tiān hù bù yǐng xiǎng。','Cảm ơn bạn rất nhiều vì đã thông cảm, chúng ta tránh giờ tự học ra để nói chuyện, không ảnh hưởng lẫn nhau nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT924','SXH4','社交软件添加好友，简单自我介绍、说明结识契机',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V924','SIT924','P1','suon_se','tuy_y',NULL,'社交软件添加新朋友后，第一句主动自我介绍、说明相遇场景，是礼貌破冰的基础社交礼仪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_01','V924','阮明',1,'你好，我是阮明，越南留学生，刚才羽毛球球场跟你搭话的人。','nǐ hǎo， wǒ shì ruǎn míng， yuè nán liú xué shēng， gāng cái yǔ máo qiú qiú chǎng gēn nǐ dā huà de rén。','Chào cậu, mình là Nguyễn Minh, du học sinh Việt Nam, lúc nãy là người bắt chuyện với cậu ở sân cầu lông đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_02','V924','小周',2,'你好，刚才打球聊了两句，特意添加好友方便之后约球场。','nǐ hǎo， gāng cái dǎ qiú liáo le liǎng jù， tè yì tiān jiā hǎo yǒu fāng biàn zhī hòu yuē qiú chǎng。','Chào cậu, lúc nãy chơi cầu lông nói chuyện vui ghê, mình kết bạn luôn cho tiện sau này rủ nhau đánh cầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_03','V924','阮明',3,'平时周四下午有空打球，有空可以在微信提前约场地。','píng shí zhōu sì xià wǔ yǒu kòng dǎ qiú， yǒu kòng kě yǐ zài wēi xìn tí qián yuē chǎng dì。','Bình thường chiều thứ Năm mình rảnh chơi cầu lông, khi nào rảnh thì nhắn WeChat hẹn sân trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_04','V924','小周',4,'没问题，我大部分周四没课，随时可以组队。','méi wèn tí， wǒ dà bù fèn zhōu sì méi kè， suí shí kě yǐ zǔ duì。','Không thành vấn đề, đa số thứ Năm mình không có tiết, lúc nào cũng có thể rủ nhóm được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_05','V924','阮明',5,'我汉语还在练习，有表达不通顺的地方麻烦多包涵。','wǒ hàn yǔ hái zài liàn xí， yǒu biǎo dá bù tōng shùn de dì fāng má fán duō bāo hán。','Tiếng Trung của mình vẫn đang luyện, chỗ nào nói chưa suôn thì mong cậu thông cảm nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_06','V924','小周',6,'互相学习，你也可以教我几句越南日常用语。','hù xiāng xué xí， nǐ yě kě yǐ jiāo wǒ jǐ jù yuè nán rì cháng yòng yǔ。','Học hỏi lẫn nhau mà, cậu cũng có thể dạy mình vài câu tiếng Việt thông dụng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_07','V924','阮明',7,'之后球场碰面再详细聊天。','zhī hòu qiú chǎng pèng miàn zài xiáng xì liáo tiān。','Lần sau gặp nhau ở sân mình nói chuyện kỹ hơn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT925','SXH4','多人出行计划出现分歧，投票协商统一游玩行程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V925','SIT925','P1','suon_se','tuy_y',NULL,'多人集体出行意见不统一时，普遍采用投票少数服从多数，落选一方配合集体安排，不单独搞分歧行程。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_01','V925','阮明',1,'现在有两个游玩方案，爬山或者城市老街逛小店，大家投票选择。','xiàn zài yǒu liǎng gè yóu wán fāng àn， pá shān huò zhě chéng shì lǎo jiē guàng xiǎo diàn， dà jiā tóu piào xuǎn zé。','Giờ có hai phương án đi chơi, leo núi hoặc dạo phố cổ ghé mấy cửa hàng nhỏ, mọi người biểu quyết chọn nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_02','V925','苏雯',2,'我倾向老街，爬山体力消耗太大，晚上还有作业要写。','wǒ qīng xiàng lǎo jiē， pá shān tǐ lì xiāo hào tài dà， wǎn shàng hái yǒu zuò yè yào xiě。','Mình nghiêng về phố cổ hơn, leo núi tốn sức quá, tối còn phải làm bài tập nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_03','V925','小林',3,'我想爬山，老街商铺人太多拍照拥挤。','wǒ xiǎng pá shān， lǎo jiē shāng pù rén tài duō pāi zhào yōng jǐ。','Mình thì muốn leo núi, phố cổ đông người quá chụp ảnh chen chúc lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_04','V925','阮明',4,'我们五个人举手表决，票数多的方案作为本周出行计划。','wǒ men wǔ gè rén jǔ shǒu biǎo jué， piào shù duō de fāng àn zuò wéi běn zhōu chū xíng jì huà。','Năm đứa mình giơ tay biểu quyết, phương án nào nhiều phiếu hơn thì lấy làm kế hoạch đi chơi tuần này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_05','V925','小林',5,'行，少数服从多数，选老街我也配合大家行程。','xíng， shǎo shù fú cóng duō shù， xuǎn lǎo jiē wǒ yě pèi hé dà jiā xíng chéng。','Được, thiểu số phục tùng đa số, chọn phố cổ thì mình cũng theo lịch trình của mọi người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_06','V925','阮明',6,'敲定老街路线，提前查公交、小吃店攻略。','qiāo dìng lǎo jiē lù xiàn， tí qián chá gōng jiāo、 xiǎo chī diàn gōng lüè。','Vậy chốt lộ trình phố cổ, tranh thủ tra trước xe buýt với mấy quán ăn vặt ngon nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_07','V925','苏雯',7,'统一行程之后，所有人周末同步出发。','tǒng yī xíng chéng zhī hòu， suǒ yǒu rén zhōu mò tóng bù chū fā。','Chốt lịch trình xong thì cuối tuần mọi người cùng xuất phát luôn nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT926','SXH4','线下聚会结束后，主动发消息平安到家，告知同行朋友',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V926','SIT926','P1','suon_se','tuy_y',NULL,'多人线下活动解散后，互相在群内报平安是通用习惯，确认所有人安全抵达住处，避免同伴失联让人担心。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_01','V926','阮明',1,'我已经平安回到宿舍，大家到家都报一声平安哈。','wǒ yǐ jīng píng ān huí dào sù shè， dà jiā dào jiā dōu bào yī shēng píng ān hā。','Mình về ký túc xá an toàn rồi nè, mọi người về tới nơi thì báo một tiếng cho yên tâm nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_02','V926','苏雯',2,'我刚到楼下，马上进宿舍，路上公交很顺畅。','wǒ gāng dào lóu xià， mǎ shàng jìn sù shè， lù shàng gōng jiāo hěn shùn chàng。','Mình vừa xuống dưới sảnh, sắp vào ký túc rồi, đường đi xe buýt thông suốt lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_03','V926','小林',3,'我还在步行回宿舍，十分钟左右到，一切顺利。','wǒ hái zài bù xíng huí sù shè， shí fēn zhōng zuǒ yòu dào， yī qiè shùn lì。','Mình vẫn đang đi bộ về ký túc, khoảng mười phút nữa là tới, mọi thứ đều ổn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_04','V926','阮明',4,'今晚聚会很开心，下次有空再约线下活动。','jīn wǎn jù huì hěn kāi xīn， xià cì yǒu kòng zài yuē xiàn xià huó dòng。','Tối nay tụ tập vui thật đấy, lần sau rảnh lại hẹn nhau đi chơi tiếp nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_05','V926','苏雯',5,'好，下周看课表再商量下次聚会时间。','hǎo， xià zhōu kàn kè biǎo zài shāng liáng xià cì jù huì shí jiān。','Ừ, tuần sau xem lịch học rồi bàn tiếp thời gian tụ tập lần tới nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_06','V926','阮明',6,'大家早点休息，晚安。','dà jiā zǎo diǎn xiū xī， wǎn ān。','Mọi người ngủ sớm nhé, chúc ngủ ngon.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT927','SXH5','社团换届竞选，为参选朋友加油，赛后安慰落选社员',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V927','SIT927','P1','twist','ban_chinh_thuc',NULL,'社团竞选落选后，身边朋友会主动安慰鼓励，国内社团氛围看重同伴支持，不会因竞选结果疏远关系。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_01','V927','阮明',1,'刚才竞选演讲你发挥特别好，可惜差几票没能当选部长。','gāng cái jìng xuǎn yǎn jiǎng nǐ fā huī tè bié hǎo， kě xī chà jǐ piào méi néng dāng xuǎn bù zhǎng。','Lúc nãy bài phát biểu tranh cử của cậu hay lắm, tiếc là thiếu vài phiếu nên không trúng cử chủ nhiệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_02','V927','小杨',2,'准备了很久还是落选，心里有点失落。','zhǔn bèi le hěn jiǔ hái shì luò xuǎn， xīn lǐ yǒu diǎn shī luò。','Chuẩn bị bao lâu vậy mà vẫn trượt, trong lòng cũng hơi buồn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_03','V927','阮明',3,'你的能力所有人都看得到，明年换届还有机会参选嘛。','nǐ de néng lì suǒ yǒu rén dōu kàn dé dào， míng nián huàn jiè hái yǒu jī huì cān xuǎn ma。','Năng lực của cậu ai cũng thấy rõ cả, năm sau bầu lại vẫn còn cơ hội ứng cử mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_04','V927','小杨',4,'下一年学业压力大，不一定有空参与社团管理。','xià yī nián xué yè yā lì dà， bù yí dìng yǒu kòng cān yù shè tuán guǎn lǐ。','Năm sau áp lực học tập nặng lắm, chưa chắc đã có thời gian tham gia quản lý câu lạc bộ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_05','V927','阮明',5,'就算不当部长，社团活动依旧可以正常参与组织工作。','jiù suàn bù dàng bù zhǎng， shè tuán huó dòng yī jiù kě yǐ zhèng cháng cān yù zǔ zhī gōng zuò。','Dù không làm chủ nhiệm thì cậu vẫn có thể tham gia tổ chức hoạt động của câu lạc bộ bình thường mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_06','V927','小杨',6,'谢谢你过来为我加油，还特意过来安慰我。','xiè xiè nǐ guò lái wèi wǒ jiā yóu， hái tè yì guò lái ān wèi wǒ。','Cảm ơn cậu đã đến cổ vũ cho mình, còn đặc biệt qua an ủi mình nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_07','V927','阮明',7,'我们是朋友，开心、失落都可以一起分担。','wǒ men shì péng yǒu， kāi xīn、 shī luò dōu kě yǐ yì qǐ fēn dān。','Tụi mình là bạn bè mà, vui hay buồn gì cũng chia sẻ cùng nhau được hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT928','SXH5','新生向高年级学长学姐请教社交、校园生活避坑经验',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V928','SIT928','P1','suon_se','ban_chinh_thuc',NULL,'高校内新生主动向高年级学长学姐请教校园、社交经验是很普遍的行为，学长学姐一般都会耐心分享实用建议。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_01','V928','阮明',1,'学长，我刚入校不太熟悉校园社交，想请教一些避坑小经验。','xué zhǎng， wǒ gāng rù xiào bù tài shú xī xiào yuán shè jiāo， xiǎng qǐng jiào yī xiē bì kēng xiǎo jīng yàn。','Anh ơi, em mới nhập học chưa quen giao tiếp trong trường, muốn xin anh vài kinh nghiệm để tránh vấp phải rắc rối ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_02','V928','学长',2,'社团不用一次性报名五六个，选一两个真正感兴趣的深耕即可。','shè tuán bù yòng yí cì xìng bào míng wǔ liù gè， xuǎn yī liǎng gè zhēn zhèng gǎn xìng qù de shēn gēng jí kě。','Câu lạc bộ không cần đăng ký một lúc năm sáu cái đâu, chọn một hai cái thật sự thích rồi đầu tư sâu là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_03','V928','阮明',3,'校外社交、兼职有哪些需要格外留意的陷阱？','xiào wài shè jiāo、 jiān zhí yǒu nǎ xiē xū yào gé wài liú yì de xiàn jǐng？','Giao tiếp bên ngoài trường, làm thêm thì có những cái bẫy nào cần đặc biệt chú ý ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_04','V928','学长',4,'陌生线下兼职、陌生网友单独见面一定要选公共场所。','mò shēng xiàn xià jiān zhí、 mò shēng wǎng yǒu dān dú jiàn miàn yí dìng yào xuǎn gōng gòng chǎng suǒ。','Việc làm thêm với người lạ ngoài đời, gặp bạn quen qua mạng thì nhất định phải chọn nơi công cộng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_05','V928','阮明',5,'和本国、中国同学相处，有什么容易产生误会的文化细节？','hé běn guó、 zhōng guó tóng xué xiāng chǔ， yǒu shén me róng yì chǎn shēng wù huì de wén huà xì jié？','Khi giao tiếp với bạn học người Việt và người Trung Quốc, có chi tiết văn hóa nào dễ gây hiểu lầm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_06','V928','学长',6,'送礼、借钱、作息边界提前沟通清楚，能减少大部分矛盾。','sòng lǐ、 jiè qián、 zuò xī biān jiè tí qián gōu tōng qīng chǔ， néng jiǎn shǎo dà bù fèn máo dùn。','Chuyện tặng quà, mượn tiền, giờ giấc sinh hoạt thì nên trao đổi rõ trước, sẽ giảm được phần lớn mâu thuẫn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_07','V928','阮明',7,'记下您的建议，避免社交踩坑吃亏。','jì xià nín de jiàn yì， bì miǎn shè jiāo cǎi kēng chī kuī。','Em ghi nhớ lời khuyên của anh, để tránh vấp phải rắc rối trong giao tiếp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT929','SXH5','班级集体短途出游，主动分担采购零食、清点人数的小事',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V929','SIT929','P1','suon_se','tuy_y',NULL,'班级集体活动大家主动分担琐碎工作，是体现集体意识、快速拉近同学关系的社交方式。') ON CONFLICT DO NOTHING;
